from datetime import date

def parse_rows(text):
    """
    Parses a tab-separated text file containing rice seed bank inventory data.

    Args:
        text: A string containing the tab-separated text data.

    Returns:
        A list of dictionaries, where each dictionary represents a row
        with values converted to appropriate Python types.
    """
    rows = text.split('\n')
    header = rows[0].split('\t')
    data = []
    for row in rows[1:]:
        values = row.split('\t')
        row_data = {}
        for i, col in enumerate(header):
            value = values[i]
            if col == 'qty_g':
                if ',' in value:
                    value = value.replace(',', '')
                try:
                    row_data[col] = int(value)
                except ValueError:
                    row_data[col] = value
            elif col == 'harvested':
                try:
                    row_data[col] = date(int(value[:4]), int(value[5:7]), int(value[8:10]))
                except ValueError:
                    row_data[col] = value
            else:
                row_data[col] = value
        data.append(row_data)
    return data
